    """
    counts = {}
    parts = text.split(' ')
    best = 0
    for item in parts:
        if parts.count(item) > best and item != '':
            best = parts.count(item)
    if best > 0:
        for item in parts:
            if parts.count(item) == best:
                counts[item] = best
    return counts

